mapper.select:
SELECT factory.id factory_id, factory.`name` factory_name, workshop.id workshop_id, workshop.`name` workshop_name, production_line.id production_line_id, production_line.`name` production_line_name, gro.id, gro.`name` FROM mes_building_groups gro LEFT JOIN mes_building_factory factory ON gro.factory_id = factory.id LEFT JOIN mes_building_workshop workshop ON gro.workshop_id = workshop.id and workshop.type=#{type} LEFT JOIN mes_building_production_line production_line ON gro.production_line_id = production_line.id
LEFT JOIN mes_building_production_line_link production_line_link ON production_line_link.production_line_id=production_line.id AND production_line_link.bool_delete_enum=0
WHERE gro.bool_delete_enum=0
AND production_line.product_type & #{doParam.productType}
AND production_line_link.link_id=#{doParam.structureClassId}
AND factory.id = #{doParam.factoryId}
AND workshop.id = #{doParam.workshopId}
AND production_line.id = #{doParam.productionLineId}
AND factory.bool_enabled_enum= 1 AND workshop.bool_enabled_enum = 1 AND production_line.bool_enabled_enum = 1 ORDER BY factory.id, workshop.id, production_line.id, gro.id

SELECT factory.id factory_id, factory.`name` factory_name, workshop.id workshop_id, workshop.`name` workshop_name, production_line.id production_line_id, production_line.`name` production_line_name, gro.id, gro.`name` FROM mes_building_groups gro LEFT JOIN mes_building_factory factory ON gro.factory_id = factory.id LEFT JOIN mes_building_workshop workshop ON gro.workshop_id = workshop.id LEFT JOIN mes_building_production_line production_line ON gro.production_line_id = production_line.id LEFT JOIN mes_building_groups_team_link groups_team_link ON groups_team_link.groups_id = gro.id LEFT JOIN mes_building_team team ON team.id = groups_team_link.team_id AND team.bool_delete_enum = 0
LEFT JOIN mes_building_production_line_link production_line_link ON production_line_link.production_line_id=production_line.id AND production_line_link.bool_delete_enum=0
WHERE gro.bool_delete_enum=0 -- AND team.bool_nest_cut_enum = 0
AND production_line.product_type & #{doParam.productType}
AND production_line_link.link_id=#{doParam.structureClassId}
AND factory.id = #{doParam.factoryId}
AND workshop.id = #{doParam.workshopId}
AND production_line.id = #{doParam.productionLineId}
AND factory.bool_enabled_enum= 1 AND workshop.bool_enabled_enum = 1 AND production_line.bool_enabled_enum = 1 ORDER BY factory.id, workshop.id, production_line.id, gro.id

SELECT factory.id factory_id, factory.`name` factory_name, workshop.id workshop_id, workshop.`name` workshop_name, production_line.id production_line_id, production_line.`name` production_line_name, gro.id, gro.`name` FROM mes_building_groups gro LEFT JOIN mes_building_factory factory ON gro.factory_id = factory.id LEFT JOIN mes_building_workshop workshop ON gro.workshop_id = workshop.id LEFT JOIN mes_building_production_line production_line ON gro.production_line_id = production_line.id
LEFT JOIN mes_building_production_line_link production_line_link ON production_line_link.production_line_id=production_line.id AND production_line_link.bool_delete_enum=0
WHERE gro.id IN(SELECT groups_id FROM mes_building_groups_team_link WHERE team_id IN (SELECT id FROM mes_building_team WHERE process_id IN (SELECT id FROM mes_building_process WHERE type=8)) AND bool_delete_enum=0) AND gro.bool_delete_enum=0
AND production_line.product_type & #{productType}
AND production_line_link.link_id=#{structureClassId}
AND factory.id = #{factoryId}
AND workshop.id = #{workshopId}
AND production_line.id = #{productionLineId}
AND factory.bool_enabled_enum= 1 AND workshop.bool_enabled_enum = 1 AND production_line.bool_enabled_enum = 1 ORDER BY factory.sort,workshop.sort,production_line.sort,gro.sort

SELECT gro.id 'groupId', gro.`name` 'groupName', line.id 'lineId', line.`name` 'lineName', workshop.id 'workshopId', workshop.`name` 'workshopName', factory.id 'factoryId', factory.`name` 'factoryName' FROM mes_building_groups gro LEFT JOIN mes_building_production_line line ON gro.production_line_id = line.id AND line.bool_delete_enum = 0 LEFT JOIN mes_building_factory factory ON gro.factory_id = factory.id AND factory.bool_delete_enum = 0 AND factory.bool_enabled_enum = 1 LEFT JOIN mes_building_workshop workshop ON gro.workshop_id = workshop.id AND workshop.bool_delete_enum = 0 AND workshop.bool_enabled_enum = 1 WHERE gro.bool_delete_enum=0 AND line.bool_enabled_enum =1
and gro.id in
#{item}

SELECT gro.* FROM mes_building_groups gro LEFT JOIN mes_building_production_line line ON line.id = gro.production_line_id AND line.bool_enabled_enum = 1 WHERE gro.bool_delete_enum = 0
AND line.name = #{productionLineName}
AND gro.name = #{groupsName}
AND line.product_type= #{productType}

SELECT gro.id 'groupId', gro.`name` 'groupName', line.id 'productionLineId', line.`name` 'productionLineName', ws.id 'workshopId', ws.`name` 'workshopName', fac.id 'factoryId', fac.`name` 'factoryName' FROM mes_building_groups gro LEFT JOIN mes_building_production_line line ON gro.production_line_id = line.id LEFT JOIN mes_building_workshop ws ON gro.workshop_id = ws.id LEFT JOIN mes_building_factory fac ON fac.id = gro.factory_id WHERE
gro.id in
#{id}

select grp.*, team.id as teamId, team.process_id, tulink.user_name as teamName from mes_building_groups grp left join mes_building_groups_team_link gtlink on grp.id = gtlink.groups_id left join mes_building_team_user_link tulink on gtlink.team_id = tulink.team_id left join mes_building_team team on tulink.team_id = team.id where grp.bool_delete_enum = 0 and gtlink.bool_delete_enum = 0 and tulink.bool_delete_enum = 0 and team.bool_delete_enum = 0 and tulink.bool_leader_enum = 1
and grp.id in
#{groupId}
